<?php require 'includes/functions.php';$p=q('SELECT p.*,c.name category,c.name_en category_en FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1 AND c.active=1',[(int)($_GET['id']??0)])->fetch();if(!$p)http_response_code(404);require 'includes/header.php';if(!$p): ?><h1><?=e(t('ไม่พบสินค้า'))?></h1><a href="products.php"><?=e(t('กลับไปเลือกสินค้า'))?></a><?php else: ?>
<p class="breadcrumb"><a href="products.php"><?=e(t('สินค้าทั้งหมด'))?></a> / <?=e(current_language()==='en'&&!empty($p['category_en'])?$p['category_en']:$p['category'])?></p><div class="product-detail"><figure class="detail-image product-photo"><?=product_image_html($p,'',false,'(max-width: 700px) 90vw, 580px')?><figcaption><?=e(product_image_note($p))?></figcaption></figure><div><span class="eyebrow"><?=e(current_language()==='en'&&!empty($p['category_en'])?$p['category_en']:$p['category'])?></span><h1><?=e(localized_name($p))?></h1><p class="price"><?=money($p['price'])?></p><p><?=e(localized_description($p))?></p><p><?=e(t('รหัส'))?> <?=e($p['sku'])?> <?=e(t('· คงเหลือ'))?> <?=(int)$p['stock']?> <?=e(t('ชิ้น'))?></p><form method="post" action="cart.php"><?=csrf()?><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="action" value="add"><?php require 'includes/variant_select.php'; ?><label><?=e(t('จำนวน'))?><input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1" required></label><button <?=$p['stock']<1?'disabled':''?>><?=e(t($p['stock']<1?'สินค้าหมด':'เพิ่มลงตะกร้า'))?></button></form></div></div><h2><?=e(t('ของน่ารักในหมวดเดียวกัน'))?></h2><div class="grid"><?php foreach(q('SELECT * FROM products WHERE category_id=? AND id<>? AND active=1 LIMIT 4',[$p['category_id'],$p['id']]) as $related)card($related);?></div><?php endif;require 'includes/footer.php'; ?>
